50	std::vector<Row> doctor_artifacts() {
51	  const fs::path root = repo_root();
52	  struct A {
53	    const char* label;
54	    const char* env;
55	    fs::path def;
56	  };
57	  // The vsim/qemu defaults come straight from the registry's resolvers
58	  // (vsim_scan_dir / builtin_qemu_arch), so doctor reports the same paths the
59	  // engine would use instead of re-deriving the env -> QEMU_BIN_DIR -> legacy
60	  // tiers.
61	  const A arts[] = {
62	      {"vsim", "VSIM_BIN", vsim_scan_dir() / "sim_ax45mpv_premium"},
63	      {"qemu64", "VSIM_QEMU", builtin_qemu_arch(64).bin_path},
64	      {"plugin", "VSIM_PLUGIN", default_plugin_path()},
65	  };
66	  std::vector<Row> rows;
67	  for (const A& a : arts) {
68	    const char* ov = std::getenv(a.env);
69	    fs::path p = (ov && *ov) ? fs::path(ov) : a.def;
70	    if (fs::is_regular_file(p))
71	      rows.push_back({a.label, "PASS", p.string()});
72	    else
73	      rows.push_back(
74	          {a.label, "FAIL", "missing " + p.string() + " -- run scripts/build_all.sh"});
75	  }
76	
77	  const fs::path fix = root / "tests" / "fixtures";
78	  size_t elfs = 0;
79	  std::error_code ec;
80	  if (fs::is_directory(fix, ec))
81	    for (const auto& e : fs::directory_iterator(fix, ec))
82	      if (e.path().extension() == ".elf") ++elfs;
83	  if (elfs > 0)
84	    rows.push_back(
85	        {"fixtures", "PASS", std::to_string(elfs) + " ELFs in " + fix.string()});
86	  else
87	    rows.push_back({"fixtures", "FAIL",
88	                    "no *.elf in " + fix.string() +
89	                        " -- run make -C tests/fixtures"});
90	  return rows;
91	}
