121	// --- toolchain --------------------------------------------------------------
122	
123	// First PATH directory holding an executable non-directory named `tool`, joined
124	// the way shutil.which reports it (dir + '/' + tool). "" if not found.
125	std::string which(const std::string& tool) {
126	  const char* path = std::getenv("PATH");
127	  if (!path) return "";
128	  const std::string p(path);
129	  for (size_t i = 0; i <= p.size();) {
130	    size_t j = p.find(':', i);
131	    if (j == std::string::npos) j = p.size();
132	    std::string dir = p.substr(i, j - i);
133	    i = j + 1;
134	    if (dir.empty()) continue;
135	    std::string cand = dir.back() == '/' ? dir + tool : dir + "/" + tool;
136	    std::error_code ec;
137	    if (::access(cand.c_str(), X_OK) == 0 && !fs::is_directory(cand, ec))
138	      return cand;
139	  }
140	  return "";
141	}
