143	// Match `^\s*(?:export\s+)?HYBRID_TOOLCHAIN\s*=\s*(.+?)\s*$`; on match set `out`
144	// to the value with surrounding whitespace, then double, then single quotes
145	// stripped (mirrors hsim._read_hybrid_toolchain).
146	bool parse_toolchain_line(const std::string& line, std::string& out) {
147	  size_t i = 0, n = line.size();
148	  auto skip_ws = [&] {
149	    while (i < n && std::isspace(static_cast<unsigned char>(line[i]))) ++i;
150	  };
151	  skip_ws();
152	  const std::string kw = "export";
153	  if (line.compare(i, kw.size(), kw) == 0 && i + kw.size() < n &&
154	      std::isspace(static_cast<unsigned char>(line[i + kw.size()]))) {
155	    i += kw.size();
156	    skip_ws();
157	  }
158	  const std::string key = "HYBRID_TOOLCHAIN";
159	  if (line.compare(i, key.size(), key) != 0) return false;
160	  i += key.size();
161	  skip_ws();
162	  if (i >= n || line[i] != '=') return false;
163	  std::string rest = line.substr(i + 1);  // everything after '='
164	  if (rest.empty()) return false;         // regex (.+?) needs >= 1 char
165	  size_t b = 0, e = rest.size();
166	  while (b < e && std::isspace(static_cast<unsigned char>(rest[b]))) ++b;
167	  while (e > b && std::isspace(static_cast<unsigned char>(rest[e - 1]))) --e;
168	  std::string val = strip_char(rest.substr(b, e - b), '"');
169	  out = strip_char(val, '\'');
170	  return true;
171	}
172	
173	// HYBRID_TOOLCHAIN: env first (non-empty wins), else the first matching
174	// assignment in config.env. "" if neither yields a value.
175	std::string read_hybrid_toolchain() {
176	  const char* env = std::getenv("HYBRID_TOOLCHAIN");
177	  if (env && *env) return env;
178	  std::ifstream f(repo_root() / "config.env");
179	  if (!f) return "";
180	  std::string line, val;
181	  while (std::getline(f, line))
182	    if (parse_toolchain_line(line, val)) return val;
183	  return "";
184	}
