222	// --- runtime ----------------------------------------------------------------
223	
224	constexpr long kDefaultJobs = 8;
225	
226	std::vector<Row> doctor_runtime() {
227	  std::vector<Row> rows;
228	  long nproc = sysconf(_SC_NPROCESSORS_ONLN);
229	  if (nproc < 1) nproc = 1;
230	  rows.push_back({"nproc", "INFO", std::to_string(nproc)});
231	
232	  std::error_code ec;
233	  if (fs::is_directory("/dev/shm", ec)) {
234	    struct statvfs vfs{};
235	    unsigned long long free_gb = 0;
236	    if (statvfs("/dev/shm", &vfs) == 0)
237	      free_gb = static_cast<unsigned long long>(vfs.f_bavail) * vfs.f_frsize /
238	                (1024ULL * 1024 * 1024);
239	    rows.push_back({"/dev/shm free", free_gb >= 4 ? "PASS" : "WARN",
240	                    std::to_string(free_gb) + " GB"});
241	  } else {
242	    rows.push_back({"/dev/shm", "WARN",
243	                    "not present -- e2e fixtures will fall back to $TMPDIR"});
244	  }
245	
246	  long suggested = std::min(nproc, kDefaultJobs);
247	  rows.push_back({"JOBS suggestion", "INFO",
248	                  std::to_string(suggested) + " (default cap = " +
249	                      std::to_string(kDefaultJobs) + ")"});
250	  return rows;
251	}
