253	// --- engines (C++-only readout, after Summary) ------------------------------
254	
255	// Reflects `list engines` from the same F2 discovery, in doctor's row idiom.
256	// INFO-tagged and printed after Summary, so it never moves the summary counts
257	// or the exit code. Discovery warnings surface as WARN rows here.
258	void print_engines_section() {
259	  Discovery disc = discover_engines();
260	  size_t w = 0;
261	  for (const EngineDescriptor& e : disc.engines) w = std::max(w, e.id.size());
262	
263	  std::printf("\nengines:\n");
264	  for (const EngineDescriptor& e : disc.engines)
265	    std::printf("  [INFO] %s  kind=%s vlen=%s triggers=%s\n",
266	                ljust(e.id, w).c_str(), e.kind.c_str(), vlen_str(e.vlen).c_str(),
267	                join(e.triggers).c_str());
268	  for (const std::string& warn : disc.warnings)
269	    std::printf("  [WARN] %s\n", warn.c_str());
270	}
