272	// The shared-mmap backing tiers (F1 resolver order) with their free space,
273	// plus WSL2 advice. INFO/WARN-tagged and printed after Summary like engines,
274	// so the carried-over report keeps byte-parity with the Python golden.
275	void print_mmap_section() {
276	  const std::vector<MmapTier> tiers = mmap_tiers();
277	  size_t w = 0;
278	  for (const MmapTier& t : tiers) w = std::max(w, t.label.size());
279	
280	  std::printf("\nmmap tiers:\n");
281	  int n = 0;
282	  for (const MmapTier& t : tiers) {
283	    struct statvfs vfs{};
284	    std::string free = "missing";
285	    if (statvfs(t.dir.c_str(), &vfs) == 0) {
286	      const double gib = static_cast<double>(vfs.f_bavail) * vfs.f_frsize /
287	                         (1024.0 * 1024 * 1024);
288	      char buf[32];
289	      std::snprintf(buf, sizeof(buf), "free: %.1f GiB", gib);
290	      free = buf;
291	    }
292	    std::printf("  [INFO] tier %d  %s  %s\n", ++n, ljust(t.label, w).c_str(),
293	                free.c_str());
294	  }
295	
296	  std::string proc_version;
297	  if (std::FILE* f = std::fopen("/proc/version", "r")) {
298	    char buf[512] = {};
299	    const size_t got = std::fread(buf, 1, sizeof(buf) - 1, f);
300	    proc_version.assign(buf, got);
301	    std::fclose(f);
302	  }
303	  std::error_code ec;
304	  for (const std::string& warn :
305	       wsl_warnings(proc_version, fs::current_path(ec).string(), tiers))
306	    std::printf("  [WARN] %s\n", warn.c_str());
307	}
