309	struct Section {
310	  const char* title;
311	  std::vector<Row> rows;
312	};
313	
314	}  // namespace
315	
316	int cmd_doctor(const Cli&) {
317	  std::vector<Section> sections = {
318	      {"artifacts", doctor_artifacts()},
319	      {"submodules", doctor_submodules()},
320	      {"toolchain", doctor_toolchain()},
321	      {"runtime", doctor_runtime()},
322	  };
323	
324	  size_t name_width = 0;
325	  for (const Section& s : sections)
326	    for (const Row& r : s.rows) name_width = std::max(name_width, r.name.size());
327	
328	  int passes = 0, fails = 0, warns = 0;
329	  for (const Section& s : sections) {
330	    std::printf("%s:\n", s.title);
331	    for (const Row& r : s.rows) {
332	      if (r.status == "PASS") ++passes;
333	      else if (r.status == "FAIL") ++fails;
334	      else if (r.status == "WARN") ++warns;
335	      std::printf("  [%-4s] %s  %s\n", r.status.c_str(),
336	                  ljust(r.name, name_width).c_str(), r.detail.c_str());
337	    }
338	    std::printf("\n");
339	  }
340	  std::printf("Summary: %d PASS, %d FAIL, %d WARN\n", passes, fails, warns);
341	
342	  print_engines_section();
343	  print_mmap_section();
344	  return fails > 0 ? 1 : 0;
345	}
